// for valid timestamps tv_nsec must be in [0, 999999999].
type ExtImageCopyCaptureFramePresentationTimeEvent struct {
	TvSecHi uint32
	TvSecLo uint32
	TvNsec  uint32
}
type ExtImageCopyCaptureFramePresentationTimeHandlerFunc func(ExtImageCopyCaptureFramePresentationTimeEvent)

// SetPresentationTimeHandler : sets handler for ExtImageCopyCaptureFramePresentationTimeEvent
func (i *ExtImageCopyCaptureFrame) SetPresentationTimeHandler(f ExtImageCopyCaptureFramePresentationTimeHandlerFunc) {
	i.presentationTimeHandler = f
}

