// ExtImageCopyCaptureCursorSession : cursor capture session
//
// This object represents a cursor capture session. It extends the base
// capture session with cursor-specific metadata.
type ExtImageCopyCaptureCursorSession struct {
	client.BaseProxy
	enterHandler    ExtImageCopyCaptureCursorSessionEnterHandlerFunc
	leaveHandler    ExtImageCopyCaptureCursorSessionLeaveHandlerFunc
	positionHandler ExtImageCopyCaptureCursorSessionPositionHandlerFunc
	hotspotHandler  ExtImageCopyCaptureCursorSessionHotspotHandlerFunc
}

// NewExtImageCopyCaptureCursorSession : cursor capture session
//
// This object represents a cursor capture session. It extends the base
// capture session with cursor-specific metadata.
func NewExtImageCopyCaptureCursorSession(ctx *client.Context) *ExtImageCopyCaptureCursorSession {
	extImageCopyCaptureCursorSessionV1 := &ExtImageCopyCaptureCursorSession{}
	ctx.Register(extImageCopyCaptureCursorSessionV1)
	return extImageCopyCaptureCursorSessionV1
}

// Destroy : delete this object
//
// Destroys the session. This request can be sent at any time by the
// client.
//
// This request doesn't affect ext_image_copy_capture_frame_v1 objects created by
// this object.
func (i *ExtImageCopyCaptureCursorSession) Destroy() error {
	defer i.Context().Unregister(i)
	const opcode = 0
	const _reqBufLen = 8
	var _reqBuf [_reqBufLen]byte
	l := 0
	client.PutUint32(_reqBuf[l:4], i.ID())
	l += 4
	client.PutUint32(_reqBuf[l:l+4], uint32(_reqBufLen<<16|opcode&0x0000ffff))
	l += 4
	err := i.Context().WriteMsg(_reqBuf[:], nil)
	return err
}

// GetCaptureSession : get image copy capturer session
//
// Gets the image copy capture session for this cursor session.
//
// The session will produce frames of the cursor image. The compositor may
// pause the session when the cursor leaves the captured area.
//
// This request must not be sent more than once, or else the
// duplicate_session protocol error is raised.
func (i *ExtImageCopyCaptureCursorSession) GetCaptureSession() (*ExtImageCopyCaptureSession, error) {
	session := NewExtImageCopyCaptureSession(i.Context())
	const opcode = 1
	const _reqBufLen = 8 + 4
	var _reqBuf [_reqBufLen]byte
	l := 0
	client.PutUint32(_reqBuf[l:4], i.ID())
	l += 4
	client.PutUint32(_reqBuf[l:l+4], uint32(_reqBufLen<<16|opcode&0x0000ffff))
	l += 4
	client.PutUint32(_reqBuf[l:l+4], session.ID())
	l += 4
	err := i.Context().WriteMsg(_reqBuf[:], nil)
	return session, err
}

type ExtImageCopyCaptureCursorSessionError uint32

// ExtImageCopyCaptureCursorSessionError :
const (
	// ExtImageCopyCaptureCursorSessionErrorDuplicateSession : get_capture_session sent twice
	ExtImageCopyCaptureCursorSessionErrorDuplicateSession ExtImageCopyCaptureCursorSessionError = 1
)

func (e ExtImageCopyCaptureCursorSessionError) Name() string {
	switch e {
	case ExtImageCopyCaptureCursorSessionErrorDuplicateSession:
		return "duplicate_session"
	default:
		return ""
	}
}

func (e ExtImageCopyCaptureCursorSessionError) Value() string {
	switch e {
	case ExtImageCopyCaptureCursorSessionErrorDuplicateSession:
		return "1"
	default:
		return ""
	}
}

func (e ExtImageCopyCaptureCursorSessionError) String() string {
	return e.Name() + "=" + e.Value()
}

// ExtImageCopyCaptureCursorSessionEnterEvent : cursor entered captured area
//
// Sent when a cursor enters the captured area. It shall be generated
// before the "position" and "hotspot" events when and only when a cursor
// enters the area.
//
// The cursor enters the captured area when the cursor image intersects
// with the captured area. Note, this is different from e.g.
// wl_pointer.enter.
type ExtImageCopyCaptureCursorSessionEnterEvent struct{}
type ExtImageCopyCaptureCursorSessionEnterHandlerFunc func(ExtImageCopyCaptureCursorSessionEnterEvent)

// SetEnterHandler : sets handler for ExtImageCopyCaptureCursorSessionEnterEvent
func (i *ExtImageCopyCaptureCursorSession) SetEnterHandler(f ExtImageCopyCaptureCursorSessionEnterHandlerFunc) {
	i.enterHandler = f
}

// ExtImageCopyCaptureCursorSessionLeaveEvent : cursor left captured area
//
// Sent when a cursor leaves the captured area. No "position" or "hotspot"
// event is generated for the cursor until the cursor enters the captured
// area again.
type ExtImageCopyCaptureCursorSessionLeaveEvent struct{}
type ExtImageCopyCaptureCursorSessionLeaveHandlerFunc func(ExtImageCopyCaptureCursorSessionLeaveEvent)

// SetLeaveHandler : sets handler for ExtImageCopyCaptureCursorSessionLeaveEvent
func (i *ExtImageCopyCaptureCursorSession) SetLeaveHandler(f ExtImageCopyCaptureCursorSessionLeaveHandlerFunc) {
	i.leaveHandler = f
}

// ExtImageCopyCaptureCursorSessionPositionEvent : position changed
//
// Cursors outside the image capture source do not get captured and no
// event will be generated for them.
//
// The given position is the position of the cursor's hotspot and it is
// relative to the main buffer's top left corner in transformed buffer
// pixel coordinates. The coordinates may be negative or greater than the
// main buffer size.
type ExtImageCopyCaptureCursorSessionPositionEvent struct {
	X int32
	Y int32
}
type ExtImageCopyCaptureCursorSessionPositionHandlerFunc func(ExtImageCopyCaptureCursorSessionPositionEvent)

// SetPositionHandler : sets handler for ExtImageCopyCaptureCursorSessionPositionEvent
func (i *ExtImageCopyCaptureCursorSession) SetPositionHandler(f ExtImageCopyCaptureCursorSessionPositionHandlerFunc) {
	i.positionHandler = f
}

// ExtImageCopyCaptureCursorSessionHotspotEvent : hotspot changed
//
// The hotspot describes the offset between the cursor image and the
// position of the input device.
//
// The given coordinates are the hotspot's offset from the origin in
// buffer coordinates.
//
// Clients should not apply the hotspot immediately: the hotspot becomes
// effective when the next ext_image_copy_capture_frame_v1.ready event is received.
//
// Compositors may delay this event until the client captures a new frame.
type ExtImageCopyCaptureCursorSessionHotspotEvent struct {
	X int32
	Y int32
}
type ExtImageCopyCaptureCursorSessionHotspotHandlerFunc func(ExtImageCopyCaptureCursorSessionHotspotEvent)

// SetHotspotHandler : sets handler for ExtImageCopyCaptureCursorSessionHotspotEvent
func (i *ExtImageCopyCaptureCursorSession) SetHotspotHandler(f ExtImageCopyCaptureCursorSessionHotspotHandlerFunc) {
	i.hotspotHandler = f
}

func (i *ExtImageCopyCaptureCursorSession) Dispatch(opcode uint32, fd int, data []byte) {
	switch opcode {
	case 0:
		if i.enterHandler == nil {
			return
		}
		var e ExtImageCopyCaptureCursorSessionEnterEvent

		i.enterHandler(e)
	case 1:
		if i.leaveHandler == nil {
			return
		}
		var e ExtImageCopyCaptureCursorSessionLeaveEvent

		i.leaveHandler(e)
	case 2:
		if i.positionHandler == nil {
			return
		}
		var e ExtImageCopyCaptureCursorSessionPositionEvent
		l := 0
		e.X = int32(client.Uint32(data[l : l+4]))
		l += 4
		e.Y = int32(client.Uint32(data[l : l+4]))
		l += 4

		i.positionHandler(e)
	case 3:
		if i.hotspotHandler == nil {
			return
		}
		var e ExtImageCopyCaptureCursorSessionHotspotEvent
		l := 0
		e.X = int32(client.Uint32(data[l : l+4]))
		l += 4
		e.Y = int32(client.Uint32(data[l : l+4]))
		l += 4

		i.hotspotHandler(e)
	}
}
